import{_ as o,r as n,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Color Picker 字段 - October CMS - 3.x","titleTemplate":false,"description":"表单小部件","frontmatter":{"subtitle":"表单小部件","shortname":"Color Picker"},"headers":[{"level":2,"title":"动态可用颜色","slug":"动态可用颜色","link":"#动态可用颜色","children":[]}],"relativePath":"3.x/zh-cn/element/form/widget-colorpicker.md","filePath":"3.x/zh-cn/element/form/widget-colorpicker.md"}'),u={name:"3.x/zh-cn/element/form/widget-colorpicker.md"};function i(d,a,k,g,m,y){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Color Picker 字段",-1)),s(e),a[1]||(a[1]=r(`<p><code>colorpicker</code> - 渲染用于选择十六进制颜色值的控件。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
</code></pre></div><p>以下<a href="./../form-fields.html">字段属性</a>受支持且常用。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示表单字段时使用的名称。</td></tr><tr><td><strong>default</strong></td><td>指定默认字符串值，可选。</td></tr><tr><td><strong>comment</strong></td><td>在字段下方放置描述性注释。</td></tr><tr><td><strong>availableColors</strong></td><td>以数组形式列出的可用颜色列表。</td></tr><tr><td><strong>allowEmpty</strong></td><td>允许空输入值。默认值：<code>false</code></td></tr><tr><td><strong>allowCustom</strong></td><td>允许选择自定义颜色。默认值：<code>true</code></td></tr><tr><td><strong>showAlpha</strong></td><td>显示不透明度滑块并设置 8 位十六进制颜色代码。默认值：<code>false</code></td></tr><tr><td><strong>showInput</strong></td><td>在颜色选择器旁边显示文本输入框并禁用可用颜色。默认值：<code>false</code></td></tr></tbody></table></div><p>您可以通过将 <code>availableColors</code> 属性设置为十六进制颜色数组来定义预设颜色。<code>allowCustom</code> 属性可用于禁止选择自定义颜色，这是可选的。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">allowCustom</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>如果 YAML 文件中未定义 <code>availableColors</code> 字段，颜色选择器将使用一组 20 个默认颜色。</p></div><p>使用 <code>showAlpha</code> 属性在颜色选择中包含不透明度，这将生成一个 8 位十六进制值。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showAlpha</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>使用 <code>showInput</code> 属性在颜色旁边显示文本输入框。此模式将禁用可用颜色，使选择和输入自定义十六进制颜色成为主要操作。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Primary Color
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">showInput</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="动态可用颜色"><a href="#动态可用颜色" class="header-anchor">#</a> 动态可用颜色</h2><p>可用颜色可以通过将 <code>availableColors</code> 设置为模型类中声明的方法名称来从模型类获取。此方法应返回与上述示例相同格式的十六进制颜色数组。此方法的第一个参数是字段名称，第二个参数是字段的当前值，第三个参数是整个表单的当前数据对象。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">color</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background
    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
    <span class="token key atrule">availableColors</span><span class="token punctuation">:</span> myColorList
</code></pre></div><p>在模型类中提供可用颜色：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">myColorList</span><span class="token punctuation">(</span><span class="token variable">$fieldName</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$formData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#000000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#111111&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;#222222&#39;</span><span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div>`,16))])}const b=o(u,[["render",i]]);export{v as __pageData,b as default};
